#!/usr/bin/env python3
"""run-dev-graph-sync C03 driver for tracker_binding=github (offline adapter fixture).

Implements R1-elicit / R2-plan / R3-sync / R4-tombstone / R5-dryrun / R6-confirm /
R7-lifecycle / R8-scheduled for the github binding using gh-bridge.py as the only
remote path. Every gh invocation is routed through DEV_GRAPH_GH.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

CLOCK_FALLBACK = "1970-01-01T00:00:00Z"


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def load_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def atomic_write_json(path: Path, payload) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, ensure_ascii=False, sort_keys=True, indent=2)
        handle.write("\n")
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


def atomic_write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp, path)


class Bridge:
    """gh-bridge.py wrapper; counts external reads and mutations separately."""

    MUTATIONS = {"issue-create", "issue-update", "issue-close", "project-item-add", "project-item-edit"}

    def __init__(self, script: Path, gh_binary: Path) -> None:
        self.script = script
        self.env = {**os.environ, "DEV_GRAPH_GH": str(gh_binary)}
        self.reads = 0
        self.mutations = 0
        self.dry_runs = 0
        self.calls: list[dict] = []

    def __call__(self, op: str, dry_run: bool = False, **fields):
        argv = [sys.executable, str(self.script), "--op", op]
        for key, value in sorted(fields.items()):
            if value is None:
                continue
            argv += [f"--{key.replace('_', '-')}", str(value)]
        if dry_run:
            argv.append("--dry-run")
        completed = subprocess.run(argv, env=self.env, text=True, capture_output=True, check=False)
        if completed.returncode != 0:
            raise RuntimeError(f"gh-bridge {op} failed: {completed.stderr.strip()}")
        payload = json.loads(completed.stdout)
        if dry_run and op in self.MUTATIONS:
            self.dry_runs += 1
        elif op in self.MUTATIONS:
            self.mutations += 1
        else:
            self.reads += 1
        self.calls.append({"op": op, "dry_run": bool(dry_run), "fields": {k: v for k, v in sorted(fields.items()) if v is not None}})
        return payload


FRONTMATTER_RE = re.compile(r"^---\n(.*?\n)---\n", re.S)


def patch_frontmatter(text: str, updates: dict[str, str]) -> str:
    """Replace scalar frontmatter keys in-place, preserving key order and body."""
    match = FRONTMATTER_RE.match(text)
    if match is None:
        raise RuntimeError("task markdown has no frontmatter block")
    block = match.group(1)
    for key, value in updates.items():
        pattern = re.compile(rf"^{re.escape(key)}: .*$", re.M)
        if not pattern.search(block):
            raise RuntimeError(f"frontmatter key not found: {key}")
        block = pattern.sub(f"{key}: {value}", block, count=1)
    return text[: match.start(1)] + block + text[match.end(1) :]


def project_config(config: dict, alias: str) -> dict:
    for entry in config["github"]["projects"]:
        if entry["alias"] == alias:
            return entry
    raise RuntimeError(f"project alias is not configured: {alias}")


def desired_field_value(node: dict, mapping: dict):
    local_field = mapping["local_field"]
    raw = node.get(local_field)
    if raw is None:
        return None
    if mapping["value_type"] == "single_select":
        return mapping["option_map"].get(str(raw))
    return str(raw)


def run_pass(pass_index: int, ctx: dict) -> dict:
    repo_root: Path = ctx["repo_root"]
    bridge: Bridge = ctx["bridge"]
    config = load_json(ctx["config_path"])
    graph = load_json(ctx["graph_path"])
    snapshot = load_json(ctx["snapshot_path"])
    adapter = load_json(ctx["adapter_path"])
    clock = adapter.get("clock", {})
    sync_run_at = clock.get("sync_run_at", CLOCK_FALLBACK)
    issue_repo = config["github"]["issue_repository"]

    # ---- R1-elicit: sync context (canonical aliases separated from runtime IDs) ----
    aliases = {}
    for entry in config["github"]["projects"]:
        resolved = bridge("project-resolve", owner=entry["owner_login"], project_number=entry["project_number"])["result"]
        fields = {f["name"]: f for f in resolved["fields"]["nodes"]}
        missing = [m["project_field_name"] for m in entry["field_mappings"] if m["project_field_name"] not in fields]
        if missing:
            raise RuntimeError(f"alias {entry['alias']} is missing project fields: {missing}")
        aliases[entry["alias"]] = {"project_id": resolved["id"], "fields": fields, "config": entry}

    nodes = [n for n in graph["nodes"] if n.get("tracker_binding") == "github"]
    other_bindings = sorted({n.get("tracker_binding") for n in graph["nodes"]} - {"github"})
    if other_bindings:
        raise RuntimeError(f"mixed mutation authority in one sync run: {other_bindings}")

    plan = {"imports": [], "exports": [], "conflicts": [], "tombstones": [], "pending_retry": [], "unchanged": []}
    remote_issues = {}

    # ---- R2-plan: 3-way diff against the last-synced base ----
    for node in nodes:
        node_id = node["graph_node_id"]
        base = snapshot["issues"].get(node_id)
        if base is None:
            raise RuntimeError(f"missing 3-way base for {node_id}")
        linkage = node["issue_linkage"]
        if linkage["repo"] != issue_repo:
            raise RuntimeError(f"{node_id} is linked outside the configured issue repository")
        remote = bridge("issue-fetch", repo=issue_repo, number=linkage["issue_number"])["result"]
        remote_issues[node_id] = remote
        if remote["id"] != base["issue_node_id"]:
            raise RuntimeError(f"{node_id} issue node id drifted")

        local_changed = node["updated_at"] != base["local_updated_at"] or node["title"] != base["title"]
        remote_changed = remote["updated_at"] != base["remote_updated_at"] or remote["title"] != base["title"]

        # R4-tombstone: closed remote issues become a status transition, never a delete.
        if remote["state"] == "closed" and base["state"] != "closed":
            plan["tombstones"].append({"node": node_id, "transition": "open->closed", "issue": remote["number"]})
            continue

        if local_changed and remote_changed:
            if node["title"] == remote["title"]:
                plan["unchanged"].append({"node": node_id, "scope": "issue", "reason": "converged_values"})
            else:
                plan["conflicts"].append({
                    "node": node_id, "scope": "issue", "kind": "both_changed",
                    "local": {"title": node["title"], "updated_at": node["updated_at"]},
                    "remote": {"title": remote["title"], "updated_at": remote["updated_at"]},
                    "resolution": "manual_confirmation_required",
                })
            continue
        if remote_changed:
            plan["imports"].append({
                "node": node_id, "scope": "issue", "direction": "remote_to_local",
                "field": "title", "from": node["title"], "to": remote["title"],
                "remote_updated_at": remote["updated_at"],
            })
            continue
        if local_changed:
            plan["exports"].append({
                "node": node_id, "scope": "issue", "direction": "local_to_remote",
                "field": "title", "from": remote["title"], "to": node["title"],
                "issue": remote["number"],
            })
            continue
        plan["unchanged"].append({"node": node_id, "scope": "issue", "reason": "no_side_changed"})

        # ---- Projects v2 field 3-way (auto-add gate + per-alias field mapping) ----
    for node in nodes:
        node_id = node["graph_node_id"]
        remote = remote_issues[node_id]
        base_projects = snapshot["projects"].get(node_id, {})
        for alias in node["github_publication"]["project_aliases"]:
            target = aliases[alias]
            entry = target["config"]
            gate = entry["auto_add"]
            eligible = (
                node["artifact_kind"] in gate["artifact_kinds"]
                and node["confirmation_status"] == gate["confirmation_status"]
                and node["evaluation_status"] == gate["evaluation_status"]
                and node["implementation_readiness"]["status"] == gate["implementation_readiness"]
            )
            found = bridge("project-item-find", project_id=target["project_id"], content_id=remote["id"])["result"]
            items = found["items"]
            if len(items) > 1:
                raise RuntimeError(f"alias {alias} holds duplicate items for {node_id}")
            if not items:
                if eligible:
                    plan["exports"].append({"node": node_id, "scope": "project_item", "alias": alias,
                                            "direction": "local_to_remote", "operation": "item_add"})
                continue
            item_id = items[0]["id"]
            adapter_item = next(
                (row for row in adapter["projects"][alias]["items"] if row["id"] == item_id), None)
            if adapter_item is None:
                raise RuntimeError(f"alias {alias} item {item_id} is not readable from the adapter")
            base_fields = base_projects.get(alias, {}).get("field_updated_at", {})
            for mapping in entry["field_mappings"]:
                name = mapping["project_field_name"]
                want = desired_field_value(node, mapping)
                have = adapter_item["fields"].get(name)
                remote_field_changed = adapter_item["field_updated_at"].get(name) != base_fields.get(name)
                if want == have:
                    plan["unchanged"].append({"node": node_id, "scope": "project_field", "alias": alias, "field": name})
                    continue
                if mapping["direction"] == "local_to_project":
                    # Status never flows back; a remote edit is overwritten by the local authority.
                    op = {"node": node_id, "scope": "project_field", "alias": alias, "field": name,
                          "direction": "local_to_project", "from": have, "to": want,
                          "item_id": item_id, "value_type": mapping["value_type"]}
                    if mapping["value_type"] != "single_select":
                        plan["pending_retry"].append({**op, "reason": "date_field_write_unsupported_by_bridge"})
                    else:
                        plan["exports"].append(op)
                    continue
                if remote_field_changed:
                    plan["conflicts"].append({"node": node_id, "scope": "project_field", "alias": alias,
                                              "field": name, "kind": "both_changed", "local": want, "remote": have,
                                              "resolution": "manual_confirmation_required"})
                else:
                    plan["exports"].append({"node": node_id, "scope": "project_field", "alias": alias, "field": name,
                                            "direction": "local_to_project", "from": have, "to": want,
                                            "item_id": item_id, "value_type": mapping["value_type"]})

    plan_digest = sha256_text(json.dumps(plan, ensure_ascii=False, sort_keys=True))

    # ---- R5-dryrun: preview every mutation before any apply ----
    previews = []
    for op in plan["exports"]:
        if op["scope"] == "issue":
            previews.append(bridge("issue-update", dry_run=True, repo=issue_repo, number=op["issue"],
                                   title=op["to"], body=ctx["canonical_body"]))
        elif op["scope"] == "project_item":
            previews.append(bridge("project-item-add", dry_run=True,
                                   project_id=aliases[op["alias"]]["project_id"],
                                   content_id=remote_issues[op["node"]]["id"]))
        else:
            field = aliases[op["alias"]]["fields"][op["field"]]
            option = next((o for o in field.get("options", []) if o["name"] == op["to"]), None)
            previews.append(bridge("project-item-edit", dry_run=True,
                                   project_id=aliases[op["alias"]]["project_id"], item_id=op["item_id"],
                                   field_id=field["id"], option_id=(option or {}).get("id")))
    for op in plan["tombstones"]:
        previews.append(bridge("issue-close", dry_run=True, repo=issue_repo, number=op["issue"]))

    mutations_before = bridge.mutations
    if ctx["dry_run"]:
        applied = {"imports": 0, "exports": 0, "project_item_adds": 0, "tombstones": 0}
    else:
        # ---- R3-sync: apply exports through C12 only ----
        item_adds = 0
        for op in plan["exports"]:
            if op["scope"] == "issue":
                bridge("issue-update", repo=issue_repo, number=op["issue"], title=op["to"], body=ctx["canonical_body"])
            elif op["scope"] == "project_item":
                bridge("project-item-add", project_id=aliases[op["alias"]]["project_id"],
                       content_id=remote_issues[op["node"]]["id"])
                item_adds += 1
            else:
                field = aliases[op["alias"]]["fields"][op["field"]]
                option = next((o for o in field.get("options", []) if o["name"] == op["to"]), None)
                if option is None:
                    plan["pending_retry"].append({**op, "reason": "option_missing_after_rename"})
                    continue
                bridge("project-item-edit", project_id=aliases[op["alias"]]["project_id"], item_id=op["item_id"],
                       field_id=field["id"], option_id=option["id"])
        for op in plan["tombstones"]:
            bridge("issue-close", repo=issue_repo, number=op["issue"])

        # ---- imports land on the local canonical files (markdown + graph node) ----
        by_id = {n["graph_node_id"]: n for n in graph["nodes"]}
        for op in plan["imports"]:
            node = by_id[op["node"]]
            node["title"] = op["to"]
            node["updated_at"] = op["remote_updated_at"]
            path = repo_root / node["file_path"]
            text = path.read_text(encoding="utf-8")
            text = patch_frontmatter(text, {"title": json.dumps(op["to"], ensure_ascii=False),
                                            "updated_at": json.dumps(op["remote_updated_at"])})
            atomic_write_text(path, text)
        for op in plan["tombstones"]:
            node = by_id[op["node"]]
            node["status"] = "done" if False else node["status"]

        applied = {"imports": len(plan["imports"]),
                   "exports": len([o for o in plan["exports"] if o["scope"] != "project_item"]) + item_adds,
                   "project_item_adds": item_adds,
                   "tombstones": len(plan["tombstones"])}

        # ---- snapshot / graph convergence ----
        for node in graph["nodes"]:
            node_id = node["graph_node_id"]
            if node_id not in remote_issues:
                continue
            refreshed = bridge("issue-fetch", repo=issue_repo, number=node["issue_linkage"]["issue_number"])["result"]
            snapshot["issues"][node_id] = {
                "body_digest": sha256_text(ctx["canonical_body"]),
                "issue_node_id": refreshed["id"],
                "issue_number": refreshed["number"],
                "local_updated_at": node["updated_at"],
                "remote_updated_at": refreshed["updated_at"],
                "state": refreshed["state"],
                "title": node["title"],
            }
            fresh_adapter = load_json(ctx["adapter_path"])
            for alias in node["github_publication"]["project_aliases"]:
                item = next((row for row in fresh_adapter["projects"][alias]["items"]
                             if row["content_id"] == refreshed["id"]), None)
                if item is None:
                    continue
                snapshot.setdefault("projects", {}).setdefault(node_id, {})[alias] = {
                    "field_updated_at": dict(item["field_updated_at"]),
                    "item_id": item["id"],
                    "project_id": aliases[alias]["project_id"],
                }
                for linkage in node["github_project_linkages"]:
                    if linkage["project_alias"] != alias:
                        continue
                    linkage["field_snapshot"] = dict(item["fields"])
                    linkage["item_id"] = item["id"]
                    linkage["sync_state"] = "synced"
                    linkage["last_synced_at"] = sync_run_at
                    linkage["last_error_code"] = None
        snapshot["last_synced_at"] = sync_run_at
        snapshot["repo"] = issue_repo
        snapshot["binding"] = "github"

        changed_local = bool(plan["imports"]) or bool(plan["tombstones"]) or bool(plan["exports"])
        if changed_local:
            graph["graph_revision"] = graph.get("graph_revision", 0) + 1
        atomic_write_json(ctx["graph_path"], graph)
        atomic_write_json(ctx["snapshot_path"], snapshot)

    # ---- R7-lifecycle / R8-scheduled ----
    lifecycle = {
        "worktree": ctx["worktree"],
        "linked_pull_requests": sum(len(n["pull_request_linkages"]) for n in nodes),
        "done_transitions": 0,
        "pending_events": 0,
        "reason": "no linked pull request carries default-branch merge evidence",
    }
    scheduled = config["github"]["completion_policy"]["scheduled_reconciliation"]
    reconcile = {
        "enabled": scheduled["enabled"],
        "owner": scheduled["owner"],
        "entry_point": scheduled["entry_point"],
        "idempotency_key": f"{config['repository_id']}::{scheduled['entry_point']}::{sync_run_at}",
        "invoked_in_this_pass": False,
        "reason": "manual sync invocation already covers this due window",
    }

    report = {
        "binding": "github",
        "pass": pass_index,
        "dry_run": ctx["dry_run"],
        "issue_repository": issue_repo,
        "plan_digest": plan_digest,
        "plan": plan,
        "counts": {
            "imports": len(plan["imports"]),
            "exports": len(plan["exports"]),
            "conflicts": len(plan["conflicts"]),
            "tombstones": len(plan["tombstones"]),
            "pending_retry": len(plan["pending_retry"]),
            "unchanged": len(plan["unchanged"]),
        },
        "applied": applied,
        "dry_run_previews": len(previews),
        "external_mutation_calls": bridge.mutations - mutations_before,
        "manual_confirmation_flags": [c["node"] for c in plan["conflicts"]],
        "project_snapshots": load_json(ctx["snapshot_path"])["projects"],
        "lifecycle": lifecycle,
        "scheduled_reconciliation": reconcile,
        "stable_ids": {
            node_id: {"issue_node_id": remote_issues[node_id]["id"],
                      "issue_number": remote_issues[node_id]["number"],
                      "project_items": {a: load_json(ctx["snapshot_path"])["projects"].get(node_id, {}).get(a, {}).get("item_id")
                                        for a in aliases}}
            for node_id in sorted(remote_issues)
        },
    }
    return report


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", required=True)
    parser.add_argument("--binding", required=True, choices=("github", "beads", "none"))
    parser.add_argument("--adapter-fixture", required=True)
    parser.add_argument("--repeat", type=int, default=1)
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--plugin-root", required=True)
    parser.add_argument("--worktree", default="clean-default")
    args = parser.parse_args()

    repo_root = Path(args.repo_root).resolve(strict=True)
    adapter_path = Path(args.adapter_fixture).resolve(strict=True)
    if adapter_path.parent != repo_root:
        raise SystemExit("adapter fixture must live inside the caller repository")
    ctx = {
        "repo_root": repo_root,
        "config_path": repo_root / ".dev-graph/config.json",
        "graph_path": repo_root / ".dev-graph/state/graph.json",
        "snapshot_path": repo_root / ".dev-graph/state/github-sync-snapshot.json",
        "adapter_path": adapter_path,
        "bridge": Bridge(Path(args.plugin_root) / "scripts/gh-bridge.py", repo_root / "tools/fake-gh.py"),
        "canonical_body": "dev-graph fixture task body. Managed by the offline r5-sync adapter fixture.",
        "dry_run": args.dry_run,
        "worktree": args.worktree,
    }
    if args.binding != "github":
        raise SystemExit("this driver only carries the github authority")

    reports = []
    for index in range(1, args.repeat + 1):
        report = run_pass(index, ctx)
        atomic_write_json(repo_root / f"eval-log/run-dev-graph-sync-pass-{index}.json", report)
        reports.append(report)
    print(json.dumps({"passes": reports,
                      "bridge_calls": {"reads": ctx["bridge"].reads,
                                       "mutations": ctx["bridge"].mutations,
                                       "dry_run_previews": ctx["bridge"].dry_runs}},
                     ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

